        "spineRY",
        "spineRZ",
        "chestRX",
        "chestRY",
        "neckRX",
        "neckRY",
        "headRX",
        "headRY",
        "headRZ",
        "shLRX",
        "shLRY",
        "shLRZ",
        "elLRX",
        "shRRX",
        "shRRY",
        "shRRZ",
        "elRRX",
        "hipLRX",
        "hipLRZ",
        "kneeLRX",
        "footLRX",
        "hipRRX",
        "hipRRZ",
