  function makeBunting(z, a, b) {
    const g = new Group();
    const mid = a.clone().lerp(b, 0.5);
    mid.y -= 0.8;
    const curve = new QuadraticBezierCurve3(a, mid, b);
    const line = new Mesh(new TubeGeometry(curve, 20, 0.02, 4, false), toonMat({ color: 5917242 }));
    g.add(line);
    const cols = [15222074, 16110919, 5220576, 9226315, 15760032, 16777215];
    const n = Math.floor(a.distanceTo(b) / 0.8);
    const tri = new BufferGeometry().setFromPoints([new Vector3(-0.22, 0, 0), new Vector3(0.22, 0, 0), new Vector3(0, -0.45, 0)]);
    tri.computeVertexNormals();
    const mats = cols.map((c) => toonMat({ color: c, side: DoubleSide, rim: 0.2, outline: false }));
    for (let i = 1; i < n; i++) {
      const p = curve.getPoint(i / n);
      const m = new Mesh(tri, mats[i % mats.length]);
      m.position.copy(p);
      m.rotation.y = Math.atan2(b.x - a.x, b.z - a.z) - Math.PI / 2;
      g.add(m);
    }
    mergeGroup(g);
    z.add(g);
    return g;
  }
