    const door = new Door(game, { id: "portcullis", object: grid, colliders: [doorCol], mode: "up", dist: 8.2, dur: 3.6 });
    z.addEntity(door);
    const wheelPos = new Vector3(8.5, 8.2, 95);
    const hub = new Group();
