    wheel.onLockedHit = () => game.hud.toast("\u98CE\u8F6E\u88AB\u8346\u68D8\u6B7B\u6B7B\u7F20\u4F4F\u4E86\u2026\u2026\u5148\u628A\u8346\u68D8\u5439\u6563\uFF01", 2.5);
